const assert = require('node:assert/strict');
const { test } = require('node:test');
const { app } = require('./helpers/app');

const close = (actual, expected, tolerance = 1e-10) => assert.ok(Math.abs(actual - expected) <= tolerance, `${actual} != ${expected}`);

test('absolute humidity and VPD agree with independent rounded vapour-pressure reference values', () => {
  const a = app();
  // Reference saturation pressure in hPa, not values generated by the app.
  for (const [T, RH, es] of [[0,100,6.112],[20,50,23.4],[30,70,42.4],[-10,80,2.86]]) {
    const expectedAH = (RH/100*es*100) / (461.5*(T+273.15))*1000;
    close(a.run(`absoluteHumidity(${T},${RH})`), expectedAH, .06);
    close(a.run(`vaporPressureDeficit(${T},${RH})`), es*(1-RH/100)/10, .006);
  }
});

test('derived humidity accepts real zero and rejects missing sensors and values outside the stated domain', () => {
  const a = app();
  assert.equal(a.run('absoluteHumidity(20,0)'), 0);
  assert.equal(a.run('vaporPressureDeficit(0,100)'), 0);
  assert.equal(a.run('dewPoint(20,0)'), null);
  for (const [T, RH] of [['null','50'],['undefined','50'],['20','null'],['20','NaN'],['Infinity','50'],['-46','50'],['61','50'],['20','101'],['20','-1']]) {
    assert.equal(a.run(`absoluteHumidity(${T},${RH})`), null);
    assert.equal(a.run(`vaporPressureDeficit(${T},${RH})`), null);
  }
  assert.equal(a.run('Number.isFinite(absoluteHumidity(-45,100)) && Number.isFinite(vaporPressureDeficit(60,0))'), true);
});

test('current derived cards use the same row and clear when either sensor disappears', () => {
  const a = app({ realRefresh:true });
  a.run('store.rows=[{ts:new Date(),temp:20,hum:50,rain:0}];refreshUI()');
  assert.equal(a.nodes.get('curAbsHum').textContent, '8.62');
  assert.equal(a.nodes.get('curVPD').textContent, '1.166');
  a.run('store.rows=[{ts:new Date(),temp:null,hum:50,rain:0}];refreshUI()');
  assert.equal(a.nodes.get('curAbsHum').textContent, '–');
  assert.equal(a.nodes.get('curVPD').textContent, '–');
  a.run('store.rows=[{ts:new Date(),temp:20,hum:0,rain:0}];refreshUI()');
  assert.equal(a.nodes.get('curAbsHum').textContent, '0.00');
});

test('derived explorer statistics use full original measurements, not the reduced graph', () => {
  const a = app();
  for (const metric of ['absHum','vpd']) {
    a.run(`store.rows=Array.from({length:10000},(_,i)=>({ts:new Date(Date.now()-i*60000),temp:i===17?50:20,hum:i%13===0?null:50}));
      el('expMetric').value='${metric}';expRange='all';buildExplorer()`);
    const fn = metric === 'absHum' ? 'absoluteHumidity' : 'vaporPressureDeficit';
    assert.equal(a.run(`chartExplorer.data.datasets[0].data.includes(${fn}(50,50))`), true);
    assert.equal(a.run('expAllPts.length'), 10000);
    assert.ok(a.run('chartExplorer.data.labels.length') <= 800);
    assert.match(a.nodes.get('expInfo').textContent, /10000 měření/);
    assert.match(a.nodes.get('expChartTitle').textContent, /vypočteno/);
    assert.equal(a.run('store.rows[17].temp'), 50);
  }
});

test('full-pair Pearson and slope match independent two-pass statistics with nulls and timestamps', () => {
  const a = app();
  assert.equal(a.run(`(() => {
    store.rows=Array.from({length:30000},(_,i)=>({ts:new Date(Date.now()-Math.floor(i/2)*300000),
      temp:i%11===0?null:10+Math.sin(i/20)*8,voltage:i%7===0?null:4+Math.sin(i/20)*.02+Math.cos(i/70)*.01}));
    const pairs=store.rows.filter(r=>Number.isFinite(r.temp)&&Number.isFinite(r.voltage));
    const mt=pairs.reduce((s,r)=>s+r.temp,0)/pairs.length,mv=pairs.reduce((s,r)=>s+r.voltage,0)/pairs.length;
    const st=pairs.reduce((s,r)=>s+(r.temp-mt)**2,0),sv=pairs.reduce((s,r)=>s+(r.voltage-mv)**2,0);
    const cov=pairs.reduce((s,r)=>s+(r.temp-mt)*(r.voltage-mv),0),s=batteryAnalysis('all');
    return s.count===pairs.length && s.eligible===30000 && Math.abs(s.r-cov/Math.sqrt(st*sv))<1e-10 &&
      Math.abs(s.slope-cov/st)<1e-10 && s.uniqueTimes===new Set(pairs.map(r=>+r.ts)).size &&
      s.days===new Set(pairs.map(r=>localDateKey(r.ts))).size;
  })()`), true);
});

test('pairing never fills a missing voltage from another row; zero and duplicate rows stay explicit', () => {
  const a = app();
  a.run(`store.rows=[{temp:0,voltage:0},{temp:1,voltage:null},{temp:null,voltage:4},{temp:0,voltage:0}]
    .map(r=>({...r,ts:new Date(2026,9,21,12)}));`);
  assert.equal(a.run('batteryAnalysis("all").count'), 2);
  assert.equal(a.run('batteryAnalysis("all").excluded'), 2);
  assert.equal(a.run('batteryAnalysis("all").uniqueTimes'), 1);
  assert.equal(a.run('batteryAnalysis("all").minV'), 0);
  assert.equal(a.run('batteryAnalysis("all").r'), null);
});

test('insufficient pairs and zero variance never fabricate a relationship; signed linear examples work', () => {
  const a = app();
  for (const count of [0,1,2,10]) {
    a.run(`store.rows=Array.from({length:${count}},(_,i)=>({ts:new Date(Date.now()-i*60000),temp:20,voltage:4+i/100}));`);
    assert.equal(a.run('batteryAnalysis("all").r'), null);
    assert.equal(a.run('batteryAnalysis("all").slope'), null);
  }
  for (const sign of [1,-1]) {
    a.run(`store.rows=Array.from({length:100},(_,i)=>({ts:new Date(Date.now()-i*60000),temp:i/10,voltage:4+${sign}*i/1000}));`);
    close(a.run('batteryAnalysis("all").r'), sign);
    close(a.run('batteryAnalysis("all").slope'), sign*.01);
  }
});

test('large offsets retain correlation rather than suffering raw sum-of-squares cancellation', () => {
  const a = app();
  a.run('store.rows=Array.from({length:1000},(_,i)=>({ts:new Date(Date.now()-i*60000),temp:1e9+i*.01,voltage:4+i*.001}));');
  close(a.run('batteryAnalysis("all").r'), 1, 1e-6);
  close(a.run('batteryAnalysis("all").slope'), .1, 1e-6);
  // Valid JS numbers can still overflow when converting V/°C to mV/°C.
  a.run('store.rows=[1,0,-1].map((n,i)=>({ts:new Date(Date.now()-i*60000),temp:n*1e-154,voltage:n*1e153}));el("batteryRange").value="all";buildBatteryAnalysis()');
  assert.doesNotMatch(a.nodes.get('batterySummary').textContent, /NaN|Infinity/);
});

test('250k pairs stay complete while both plots are bounded and preserve real extrema', () => {
  const a = app();
  a.run(`globalThis.fixtureTime=Date.now();store.rows=Array.from({length:250000},(_,i)=>({ts:new Date(fixtureTime-i*300000),
    temp:i===17?85:Math.sin(i/30)*8,voltage:i===19?0:4+Math.sin(i/29)*.2}));globalThis.s=batteryAnalysis('all');`);
  assert.equal(a.run('s.count'), 250000);
  assert.equal(a.run('store.rows[17].temp'), 85);
  assert.ok(a.run('s.xy.length') <= 582);
  assert.ok(a.run('s.timeTemp.length') <= 800);
  assert.equal(a.run('s.timeTemp.some(p=>p.y===85) && s.timeVoltage.some(p=>p.y===0)'), true);
  assert.equal(a.run('s.xy.some(p=>p.x===85) && s.xy.some(p=>p.y===0)'), true);
  assert.equal(a.run('s.xy.every(p=>{const row=store.rows[(fixtureTime-p.ts)/300000];return row && row.temp===p.x && row.voltage===p.y})'), true);
  assert.equal(a.run('Object.hasOwn(s,"pairs")'), false);
});

test('one-range cache avoids repeated scans and a seven-day view uses the latest measurement as anchor', () => {
  const a = app();
  a.run(`globalThis.visits=0;store.rows=new Proxy(Array.from({length:10000},(_,i)=>({
    ts:new Date(+new Date(2020,0,10)-i*300000),temp:i/100,voltage:4+i/10000
  })),{get(target,key,receiver){if(/^\\d+$/.test(String(key)))visits++;return Reflect.get(target,key,receiver)}});
    dataAggregates();globalThis.start=visits;globalThis.first=batteryAnalysis('7');globalThis.after=visits;`);
  assert.equal(a.run('first.count'), 2017);
  assert.ok(a.run('after-start') < 2025);
  assert.equal(a.run('batteryAnalysis("7")===first'), true);
  assert.equal(a.run('visits'), a.run('after'));
  a.run('batteryAnalysis("30")');
  assert.equal(a.run('dataAggregates().battery.range'), '30');
  assert.equal(a.run('batteryAnalysis("bad").count'), 2017);
});

test('data correction, deletion, CSV and MQTT invalidate battery results, and reset clears old plots', async () => {
  const a = app();
  a.run('store.rows=[3,2,1].map((temp,i)=>({ts:new Date(Date.now()-i*60000),temp,voltage:temp}));el("batteryRange").value="all";buildBatteryAnalysis();store.rows[2].voltage=50;invalidateDerivedData()');
  assert.equal(a.run('batteryAnalysis("all").maxV'), 50);
  const done = a.run('parseAndStore("Datum,Cas,Teplota,Tlak,Vlhkost,Prirustek,Dest,Nadrz,Napeti\\n20.10.2026,12:00,10,1010,60,0,0,,4")');
  a.tick(); await done;
  assert.equal(a.run('batteryAnalysis("all").count'), 1);
  a.run('CFG.source="both";CFG.mqttHost="test.example";connectMQTT()');
  a.clients[0].onMessageArrived({payloadString:'{"temp":30,"voltage":0}'});
  assert.equal(a.run('batteryAnalysis("all").count'), 2);
  assert.equal(a.run('batteryAnalysis("all").minV'), 0);
  a.run('switchStation(1);buildBatteryAnalysis()');
  assert.equal(a.run('chartBatteryXY.data.datasets[0].data.length'), 0);
  assert.match(a.nodes.get('batterySummary').textContent, /žádné platné páry/);
});

test('battery plots construct lazily and are reused while summary counts describe originals', () => {
  const a = app();
  assert.equal(a.run('chartBatteryTime'), null);
  a.run('store.rows=[3,2,1].map((temp,i)=>({ts:new Date(Date.now()-i*60000),temp,voltage:temp}));el("batteryRange").value="all";buildBatteryAnalysis();globalThis.chart=chartBatteryXY;buildBatteryAnalysis()');
  assert.equal(a.run('chartBatteryXY===chart'), true);
  assert.match(a.nodes.get('batterySummary').textContent, /3 platných párů z 3/);
  assert.match(a.nodes.get('batterySummary').textContent, /Pearson r \(popisný\): 1.000/);
  assert.equal(a.requests.length, 0);
});

test('reduced motion applies initially and live changes retain the always-unanimated plots', () => {
  const a = app({reducedMotion:true});
  assert.equal(a.run('chart24.options.animation'), false);
  assert.equal(a.run('chartCompare.options.animation'), false);
  a.motion(false);
  assert.equal(a.run('chart24.options.animation.duration'), 300);
  assert.equal(a.run('chartOverview.options.animation.duration'), 300);
  assert.equal(a.run('chartExplorer.options.animation'), false);
  a.motion(true);
  assert.equal(a.run('chart24.options.animation'), false);
  assert.equal(a.run('chartExplorer.options.animation'), false);
});
